<script setup lang="ts">
import { ref, reactive, computed } from 'vue'
import { Refresh, Connection } from '@element-plus/icons-vue'
import { api, put, post, errorText } from '../api'
import { useLoad } from '../composables'
import { ElMessage, ElMessageBox } from 'element-plus'
const health=ref<any>(null),saving=ref(false),syncing=ref(false),formError=ref(''),loaded=ref(false),originalLiveness=ref(false)
const form=reactive({livenessEnabled:true,recognitionThreshold:0.5,candidateMargin:0.08,calibrationConfirmed:false})
const {loading,error,load}=useLoad(async()=>{loaded.value=false;const [s,h]=await Promise.all([api('/settings'),api('/system/health')]);Object.assign(form,{livenessEnabled:s.livenessEnabled,recognitionThreshold:s.recognitionThreshold,candidateMargin:s.candidateMargin,calibrationConfirmed:s.calibrationConfirmed});originalLiveness.value=s.livenessEnabled;health.value=h;loaded.value=true})
function invalidateCalibration(){form.calibrationConfirmed=false}
function state(v:any){if(v===true||v==='UP'||v==='READY'||v==='OK'||v==='HEALTHY')return '正常';if(v===false||v==='DOWN'||v==='UNAVAILABLE')return '不可用';if(typeof v==='object'&&v)return v.status||'待确认';return v||'未知'}
const healthCards=computed(()=>[{label:'业务数据库',value:state(health.value?.database)},{label:'算法服务',value:state(health.value?.algorithm)},{label:'识别模型',value:state(health.value?.model)},{label:'人员库同步',value:health.value?health.value.gallerySynced?'已同步':'待同步':'未知'}])
async function save(){if(!loaded.value)return;try{if(form.livenessEnabled!==originalLiveness.value)await ElMessageBox.confirm('动作检测开关变更将立即使未完成打卡会话失效，公共设备需要重新开始。','确认调整动作检测',{confirmButtonText:'保存设置',cancelButtonText:'取消',type:'warning'});saving.value=true;formError.value='';await put('/settings',form);ElMessage.success('识别设置已保存');await load()}catch(e){if(e!=='cancel'&&e!=='close')formError.value=errorText(e)}finally{saving.value=false}}
async function sync(){syncing.value=true;try{await post('/system/sync-gallery');ElMessage.success('人员库已同步');await load()}catch(e){ElMessage.error(errorText(e))}finally{syncing.value=false}}
</script>
<template><div class="page-head"><div><div class="eyebrow">SYSTEM & RECOGNITION</div><h1>系统运行</h1><p>检查服务状态，管理识别与随机动作验证。</p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新状态</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="panel" v-loading="loading"><div class="panel-head"><div><h2>运行健康状态</h2><p>以业务服务返回的实际检测结果为准</p></div><el-button :icon="Connection" :loading="syncing" @click="sync">重新同步人员库</el-button></div><div class="health-grid"><div v-for="item in healthCards" :key="item.label" class="health-card">{{item.label}}<strong>{{item.value}}</strong></div></div><div class="help-text">人员库版本：{{health?.galleryVersion??'—'}}<br>{{health?.detail||'人员库同步失败时，系统将暂停新打卡，防止使用过期身份数据。'}}</div></div><div class="panel section-gap"><div class="panel-head"><div><h2>识别与动作检测</h2><p>阈值需要使用独立样本完成校准，再固定参数进行测试</p></div></div><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><div class="setting-row"><div><h3>随机动作检测</h3><p>要求完成眨眼与张嘴的随机动作顺序，连续检查身份一致性。</p></div><el-switch v-model="form.livenessEnabled" :disabled="!loaded" active-text="开启" inactive-text="关闭"/></div><div class="rule-hint section-gap">{{form.livenessEnabled?'开启后须完成动作验证。此方式用于研究对静态照片的抵抗能力，不等同于商业级防伪认证。':'关闭后仍要求单人、画面质量与连续身份识别通过；考勤事件将记录动作检测为「跳过」。'}}</div><el-alert v-if="loaded && !form.calibrationConfirmed" title="这组参数尚未确认校准。保存为未校准状态后，公共打卡将保持关闭。请使用独立校准样本确定阈值并保留报告，再确认保存；不要把默认参数勾选为已校准。" type="warning" show-icon :closable="false" class="section-gap"/><el-form v-if="loaded" label-position="top" class="compact-form section-gap"><div class="form-grid"><el-form-item label="识别相似度阈值"><el-input-number v-model="form.recognitionThreshold" @change="invalidateCalibration" :min="0.1" :max="1" :step="0.01" :precision="3" :disabled="!loaded"/><div class="help-text">第一候选必须达到该阈值。</div></el-form-item><el-form-item label="第一、第二候选最小分差"><el-input-number v-model="form.candidateMargin" @change="invalidateCalibration" :min="0" :max="1" :step="0.01" :precision="3" :disabled="!loaded"/><div class="help-text">仅有一个有效人员时不使用候选分差。</div></el-form-item></div><el-form-item><el-checkbox v-model="form.calibrationConfirmed" :disabled="!loaded">已使用独立校准样本确认以上参数，并保留校准记录</el-checkbox></el-form-item><el-button type="primary" :loading="saving" :disabled="!loaded" @click="save">保存识别设置</el-button></el-form></div></template>
